XmlStreamWriter writer = new XmlStreamWriter();
writer.writeStartDocument('UTF-8', '1.0');
writer.setDefaultNamespace('urn:base');
writer.writeStartElement('', 'root', 'urn:base');
writer.writeDefaultNamespace('urn:base');
writer.writeNamespace('x', 'urn:x');
writer.writeAttribute('x', 'urn:x', 'id', 'A&B');
writer.writeComment('note');
writer.writeProcessingInstruction('pi', 'go');
writer.writeCData('<raw>');
writer.writeStartElement('x', 'child', 'urn:x');
writer.writeCharacters('Tom & Sue');
writer.writeEndElement();
writer.writeEmptyElement('', 'leaf', 'urn:base');
writer.writeEndElement();
writer.writeEndDocument();
String xml = writer.getXmlString();
System.assert(xml.contains('<?xml version="1.0" encoding="UTF-8"?>'));
System.assert(xml.contains('<root xmlns="urn:base" xmlns="urn:base" xmlns:x="urn:x" x:id="A&amp;B">'));
System.assert(xml.contains('<!--note-->'));
System.assert(xml.contains('<?pi go?>'));
System.assert(xml.contains('<![CDATA[<raw>]]>'));
System.assert(xml.contains('<x:child xmlns:x="urn:x">Tom &amp; Sue</x:child>'));
System.assert(xml.contains('<leaf xmlns="urn:base"/>'));
System.assert(xml.endsWith('</root>'));
System.assertEquals(xml, writer.toString());
writer.close();

